window.LION_KB={"meta": {"name": "Lions Guide (unofficial)", "built": "2026-11-18", "note": "Curated seed knowledge base. Paraphrased from lionsclubs.org pages and Lions-affiliated sites; each entry links to its source. Run the crawler to add the full resource center.", "version": "0.9.8", "checked": "2026-11-18", "build": "2026-11-18 18:52 UTC", "logo": "logo.png"}, "sources": {"mission-history": {"url": "https://www.lionsclubs.org/en/discover-our-clubs/interactive-timeline", "label": "Lions Clubs International: Our History", "tier": "official"}, "about-node": {"url": "https://www.lionsclubs.org/en/about-us/our-organization/about-lions-international", "label": "Lions Clubs International: About", "tier": "official"}, "new-members": {"url": "https://www.lionsclubs.org/en/resources-for-members/new-members", "label": "New Member Welcome", "tier": "official"}, "mrc": {"url": "https://lionsclubs.org/en/member-resource-center", "label": "Member Resource Center", "tier": "official"}, "service-programs": {"url": "https://lionsclubs.org/en/service-programs", "label": "Service Programs", "tier": "official"}, "club-types": {"url": "https://lionsclubs.org/node/14991", "label": "Club and membership types", "tier": "official"}, "join": {"url": "https://lionsclubs.org/join", "label": "Join Lions", "tier": "official"}, "ethics": {"url": "https://www.lionsclubs.org/sites/default/files/Board-Policy-Manual/Chapter_6_en.pdf", "label": "Board Policy Manual, Chapter VI: Code of Ethics", "tier": "official"}, "gst": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/gst-toolbox", "label": "Global Service Team Toolbox", "tier": "official"}, "campus": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/campus-lions-club", "label": "Campus Lions Club", "tier": "official"}, "leo-faqs": {"url": "https://lionsclubs.org/en/resources-for-members/resource-center/leo-faqs", "label": "Leo Club FAQs", "tier": "official"}, "leo-lion": {"url": "https://lionsclubs.org/en/resources-for-members/resource-center/leo-lion-program", "label": "Leo-Lion Program", "tier": "official"}, "lcif-blog": {"url": "https://lionsclubs.org/en/blog/A-World-in-Need,-a-Foundation-of-Support", "label": "A World in Need, a Foundation of Support (LCIF)", "tier": "official"}, "gma": {"url": "https://lionsclubs.org/en/global", "label": "Global Membership Approach", "tier": "official"}, "young-lions": {"url": "https://lionsclubs.org/hi/node/16981", "label": "Young Lions hub", "tier": "official"}, "options": {"url": "https://www.lionsclubs.org/node/18641", "label": "Membership options", "tier": "official"}, "leaders-page": {"url": "https://www.lionsclubs.org/en/discover-our-clubs/our-leaders", "label": "Lions Clubs International: Our Leaders", "tier": "official"}, "lcif-toolkit": {"url": "https://www.lionsclubs.org/en/member-resource-center/leaders/resources/lcif-leadership-toolkit", "label": "LCIF Leadership Toolkit", "tier": "official"}, "brand-page": {"url": "https://www.lionsclubs.org/en/resources-for-members/brand-guidelines", "label": "Brand Guidelines, Logos and Brand", "tier": "official"}, "pg-pay": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/payment-instructions", "label": "Payment Instructions", "tier": "official"}, "pg-fin": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/finance-resources", "label": "Finance Resources", "tier": "official"}, "pg-svc": {"url": "https://www.lionsclubs.org/en/member-resource-center/service/resources/service-journey/service-reporting", "label": "Service Reporting", "tier": "official"}, "pg-ins": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/insurance", "label": "Insurance", "tier": "official"}, "pg-cert": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/certificate-of-insurance", "label": "Certificate of Insurance", "tier": "official"}, "pg-mg": {"url": "https://www.lionsclubs.org/en/member-resource-center/grants-and-awards/foundation-grants/lcif-grants-toolkit/matching-grant", "label": "Matching Grant Program", "tier": "official"}, "pg-leo": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/start-a-leo-club", "label": "Starting a Leo Club", "tier": "official"}, "pg-stu": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/student-member-program", "label": "Student Member Program", "tier": "official"}, "pg-new": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/start-a-new-club", "label": "Start a New Club", "tier": "official"}, "pg-rec": {"url": "https://www.lionsclubs.org/en/member-resource-center/membership/increase-membership/member-recruitment", "label": "Member Recruitment", "tier": "official"}, "pg-dg": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/district-governors", "label": "Managing Your District (district governors)", "tier": "official"}, "pg-club": {"url": "https://www.lionsclubs.org/en/member-resource-center/leaders/club/managing-your-club", "label": "Managing Your Club", "tier": "official"}, "pg-mem": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/club-membership-chairperson", "label": "Club Membership Chairperson", "tier": "official"}, "pg-mkt": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/club-marketing-communications-chairperson", "label": "Club Marketing", "tier": "official"}, "pg-md": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/managing-your-multiple-district", "label": "Managing Your Multiple District", "tier": "official"}, "pg-helen": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/helen-keller", "label": "Helen Keller", "tier": "official"}, "rc-library": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center", "label": "Resource Center", "tier": "official"}, "pg-fam": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/family-membership", "label": "Family Membership", "tier": "official"}, "pg-legal": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/legal-resources", "label": "Legal Resources", "tier": "official"}, "pg-zone": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/zone-region-chairpersons", "label": "Managing Your Zone and Region", "tier": "official"}, "pg-gat": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/global-action-team", "label": "Global Action Team (GAT)", "tier": "official"}, "pg-gatr": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/global-action-team-roles-resources", "label": "Global Action Team (GAT) Roles and Resources", "tier": "official"}, "pg-gmt": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/gmt-and-get-toolkit", "label": "Global Membership Team and Global Extension Team Toolbox", "tier": "official"}, "pg-glt": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/glt-toolbox", "label": "Global Leadership Team Toolbox", "tier": "official"}, "pg-gst": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/gst-toolbox", "label": "Global Service Team Toolbox", "tier": "official"}}, "tour": ["what-is-lions", "mission-vision", "history", "global-causes", "lcif", "club-types", "how-to-join", "new-member-first-steps"], "entries": [{"id": "what-is-lions", "cat": "Basics", "level": "new", "title": "What is Lions Clubs International?", "questions": ["what is lions club", "what is lionism", "who are the lions", "tell me about lions clubs international", "what do lions do", "is lions a service club", "how many members does lions have", "how many clubs are there", "how many countries are lions in", "how big is lions clubs international", "are lions a religious group"], "answer": "Lions Clubs International is the world's largest service club organisation. Ordinary people join local clubs, called Lions clubs, and volunteer their time and money to help their communities and people in need. A member is called a Lion. The motto is \"We Serve\".", "facts": ["About 1.4 million members in roughly 49,000 to 50,000 clubs", "Active in over 200 countries and geographic areas", "Over 100 years of service, founded 1917", "Lions serve hundreds of millions of people every year", "Lions and Leos serve through eight global causes and other local projects"], "tags": ["lions", "lionism", "overview", "service club", "volunteer", "organization", "organisation", "about"], "related": ["mission-vision", "history", "global-causes", "how-to-join"], "src": ["new-members", "mission-history"]}, {"id": "mission-vision", "cat": "Basics", "level": "new", "title": "Mission and vision", "questions": ["what is the mission of lions", "lions vision statement", "why do lions exist", "what is lions mission statement"], "answer": "The mission of Lions Clubs International is to empower Lions clubs, volunteers and partners to improve health and wellbeing, strengthen communities, and support those in need through humanitarian service and grants that impact lives globally, and encourage peace and international understanding.", "facts": ["Mission wording is from Lions Clubs International's own About page"], "tags": ["mission", "vision", "purpose", "goal", "why"], "related": ["core-values"], "src": ["about-node"]}, {"id": "code-of-ethics", "cat": "Values", "level": "new", "title": "The Lions Code of Ethics", "questions": ["lions code of ethics", "what are the ethics of lions", "lion rules of conduct", "lions values for members", "how should a lion behave"], "answer": "The Code of Ethics is a personal guide for how each Lion should act. In plain words: work with quality and industry, seek success but never at the cost of self-respect, do not build yourself up by tearing others down, settle doubts about right and wrong against yourself, treat friendship as an end and not a means, be a good citizen, help those in distress, and be careful with criticism and generous with praise.", "facts": ["The Code of Ethics is in Chapter VI of the Board Policy Manual on lionsclubs.org"], "tags": ["ethics", "code", "conduct", "behaviour", "behavior", "integrity", "rules"], "related": ["core-values"], "src": ["ethics"]}, {"id": "core-values", "cat": "Values", "level": "new", "title": "Lions core values", "questions": ["lions core values", "what values do lions have", "lions ethical standards", "integrity accountability lions"], "answer": "Lions' ethical standards rest on core values: commitment to service, dedication to excellence, appreciation for diversity, dynamic collaboration, personal and professional integrity, and a spirit of innovation. The association says it has no tolerance for ethical violations.", "facts": ["Also stressed: safeguarding association assets, honouring commitments, and teamwork", "Source is the Board Policy Manual, Chapter VI"], "tags": ["values", "service", "excellence", "diversity", "integrity", "innovation", "accountability", "teamwork"], "related": ["code-of-ethics", "mission-vision"], "src": ["ethics"]}, {"id": "global-causes", "cat": "Service", "level": "new", "title": "Global causes: what Lions work on", "questions": ["what are the global causes", "what causes do lions support", "areas of service lions", "how many global causes", "five global causes", "eight global causes", "how many causes do lions have", "what are lions eight causes", "our global causes"], "answer": "Lions' website lists eight global causes: childhood cancer, diabetes, disaster relief, the environment, humanitarian aid, hunger, vision and youth. Earlier Lions material spoke of five global causes (diabetes, vision, hunger, the environment and childhood cancer), with disaster relief, youth programs and wider humanitarian work as further service areas. Every club can pick the causes that fit its community, and also serve local needs outside them.", "facts": ["The eight causes: Childhood cancer, Diabetes, Disaster relief, Environment, Humanitarian, Hunger, Vision, Youth", "The five long-standing focus areas are Diabetes, Vision, Hunger, Environment and Childhood Cancer", "Each cause has beginner, intermediate and advanced project ideas for clubs", "Clubs can also serve local needs outside these causes"], "tags": ["causes", "global causes", "service", "projects", "focus areas", "what lions do"], "related": ["cause-diabetes", "cause-vision", "cause-hunger", "cause-environment", "cause-childhood-cancer", "disaster-relief"], "src": ["service-programs", "join", "lcif-blog"]}, {"id": "cause-diabetes", "cat": "Service", "level": "new", "title": "Diabetes", "questions": ["lions diabetes", "diabetes screening lions", "diabetes camps", "strides for diabetes", "what do lions do about diabetes", "diabetes support group"], "answer": "Lions work to reduce how common diabetes is and to improve life for people living with it. Clubs run Type 2 diabetes screening events, \"Strides\" walks and runs that raise awareness, diabetes camps for young people, and peer support groups.", "facts": ["Type 2 Diabetes Screening: clubs use step-by-step guides", "Strides for Diabetes Awareness: any physical activity, such as a run or dance event", "Diabetes Camps: help young people build diabetes management skills", "Diabetes Support Groups: peer groups sponsored by a club or district"], "tags": ["diabetes", "sugar", "screening", "camp", "health", "strides"], "related": ["global-causes", "lcif"], "src": ["service-programs"]}, {"id": "cause-vision", "cat": "Service", "level": "new", "title": "Vision and eye care", "questions": ["lions vision", "eye care lions", "vision screening", "eye bank", "lions kidsight", "recycle eyeglasses", "donate glasses", "sightfirst", "blindness prevention"], "answer": "Vision is Lions' oldest cause. Clubs screen children and adults for vision problems, run the KidSight program for children from 6 months old, sponsor eye banks that supply eye tissue for sight restoration, and collect used eyeglasses for people who cannot afford them.", "facts": ["Vision Screening: with medical professionals and community leaders", "Lions KidSight: screening and referral from age 6 months", "Lions Eye Banks: recover, test, store and distribute eye tissue", "Eyeglass Recycling: used glasses go to the Lions Recycle For Sight program"], "tags": ["vision", "eye", "eyes", "sight", "blind", "blindness", "glasses", "eyeglasses", "cataract", "screening", "kidsight", "eye bank"], "related": ["helen-keller", "global-causes", "lcif"], "src": ["service-programs", "lcif-blog"]}, {"id": "cause-hunger", "cat": "Service", "level": "new", "title": "Hunger", "questions": ["lions hunger", "food bank lions", "what do lions do about hunger", "lions food security", "feed the hungry"], "answer": "Through the hunger cause, Lions work to make sure everyone in a community has access to nutritious food. Clubs support food banks and food distribution, and LCIF grants can fund food bank and distribution infrastructure, transport, and commercial refrigeration and freezers.", "facts": ["Goal: improve food security and access to nutritious food", "Grants can pay for food bank equipment and transport"], "tags": ["hunger", "food", "nutrition", "food bank", "malnutrition"], "related": ["global-causes", "lcif-grants"], "src": ["join", "lcif-blog"]}, {"id": "cause-environment", "cat": "Service", "level": "new", "title": "Environment", "questions": ["lions environment", "lions clean water", "environment projects", "tree planting lions", "lions sanitation"], "answer": "The environment cause is about protecting and restoring the natural world to improve people's wellbeing. LCIF funding in this area has paid for water tanks, wells and pumps, water purification for schools and clinics, and toilets and sanitation where none exist.", "facts": ["Goal: sustainably protect and restore the environment", "LCIF Campaign 100 material noted that at least 1.8 billion people use drinking water contaminated by faecal matter"], "tags": ["environment", "water", "sanitation", "green", "climate", "trees", "clean"], "related": ["global-causes", "lcif-grants"], "src": ["join", "lcif-blog"]}, {"id": "cause-childhood-cancer", "cat": "Service", "level": "new", "title": "Childhood cancer", "questions": ["lions childhood cancer", "children with cancer", "what do lions do for kids with cancer", "pediatric oncology"], "answer": "Lions support children and families affected by childhood cancer. Funding has gone to pediatric oncology services in developing countries, medical and lab equipment, vehicles for patient travel, and family lodging and camp facilities. Lions also work with the partner Global HOPE to improve standards of care.", "facts": ["A Childhood Cancer Grant program exists, with its own criteria and application form", "Campaign 100 material: a child is diagnosed about every two minutes; survival is around 80% in high-income countries but may be only 10 to 20% in low- and middle-income countries"], "tags": ["childhood cancer", "cancer", "children", "kids", "hospital", "oncology", "family"], "related": ["global-causes", "lcif-grants"], "src": ["join", "lcif-blog"]}, {"id": "disaster-relief", "cat": "Service", "level": "new", "title": "Disaster relief", "questions": ["lions disaster relief", "flood relief", "earthquake help lions", "disaster relief fund", "emergency grants"], "answer": "Lions respond when disasters hit, providing immediate needs like food, water, clothing and medical supplies, and later helping rebuild homes and facilities. People can donate to the Disaster Relief Fund, which is reserved only for disaster relief.", "facts": ["LCIF has invested about US$130 million in disaster-related grants since 1970 (Campaign 100 material)", "Donations to LCIF go to either the Empowering Service Fund or the Disaster Relief Fund"], "tags": ["disaster", "relief", "flood", "earthquake", "emergency", "hurricane", "fund"], "related": ["lcif", "lcif-grants"], "src": ["lcif-blog", "mrc"]}, {"id": "youth", "cat": "Service", "level": "new", "title": "Youth programs", "questions": ["lions youth programs", "lions for kids", "peace poster contest", "youth camps and exchange", "lions quest", "how do lions help young people"], "answer": "Lions run several programs for young people: Leo clubs for ages 12 to 30, the Youth Camps and Exchange program that promotes understanding and peace, the annual Peace Poster and Peace Essay contests, and Lions Quest, a school-based program for young people.", "facts": ["Youth Camps and Exchange excludes tourism, academic study and employment", "Lions Quest has reached 17+ million students in over 100 countries (Campaign 100 material)", "Peace Poster and Essay entries move from club to district to multiple district, then to Lions headquarters"], "tags": ["youth", "kids", "children", "students", "peace poster", "essay", "camp", "exchange", "lions quest", "school"], "related": ["leo-clubs", "young-lions"], "src": ["service-programs", "lcif-blog", "mrc"]}, {"id": "service-programs", "cat": "Service", "level": "member", "title": "Service programs clubs can run", "questions": ["lions service programs", "service project ideas", "what projects can my club do", "project planners", "lions programs list"], "answer": "Lions International offers ready-made service programs so clubs do not start from scratch: Type 2 Diabetes Screening, Strides for Diabetes Awareness, Diabetes Camps and Support Groups, Vision Screening, Lions KidSight, Lions Eye Banks, Eyeglass Recycling, and Youth Camps and Exchange. Downloadable Service Project Planners and beginner-to-advanced ideas exist for each cause.", "facts": ["Projects are grouped by global cause", "The Global Service Team site gathers the planners, ideas and grants"], "tags": ["programs", "projects", "planner", "ideas", "club projects"], "related": ["gst", "global-causes"], "src": ["service-programs", "gst"]}, {"id": "lcif", "cat": "Foundation", "level": "new", "title": "LCIF: the Lions foundation", "questions": ["what is lcif", "lions clubs international foundation", "what is the lions foundation", "lcif history", "who funds lcif", "how is lcif funded"], "answer": "LCIF, the Lions Clubs International Foundation, is the charitable arm of Lions. Founded in 1968, it gives grants that power Lions' service, and has awarded over US$1.3 billion so far. Its work centres on three goals: health and well-being, stronger communities, and support for people in need.", "facts": ["Founded 1968", "Funded by Lions, corporate, government and foundation partners, and other supporters", "Grants support Lions' local and global projects", "Donations on lionsclubs.org support LCIF"], "tags": ["lcif", "foundation", "grants", "charity", "donate", "funding"], "related": ["lcif-grants", "disaster-relief", "global-causes"], "src": ["new-members", "lcif-blog"]}, {"id": "lcif-grants", "cat": "Foundation", "level": "member", "title": "What LCIF grants and donations pay for", "questions": ["how do i get an lcif grant", "what do lcif grants fund", "where does my donation go", "lions grants", "campaign 100", "how to donate to lions"], "answer": "LCIF grants have paid for expanded eye care, education programs, disaster recovery, diabetes screening and camps, pediatric cancer equipment and family lodging, food bank infrastructure, and clean water and sanitation. Donations go to one of two funds: the Empowering Service Fund for all causes, or the Disaster Relief Fund for disasters only.", "facts": ["Campaign 100 was LCIF's centennial fundraising campaign", "Each grant type has its own criteria and application form; check the Member Resource Center for the current ones"], "tags": ["grants", "donate", "donation", "campaign 100", "funding", "empowering service fund"], "related": ["lcif", "disaster-relief"], "src": ["lcif-blog", "gst"]}, {"id": "how-to-join", "cat": "Joining", "level": "new", "title": "How to join Lions", "questions": ["how do i join lions", "how to become a lion", "join lions club", "how can i become a member", "find a lions club near me", "club locator", "can i join", "is there a lions club in my city", "is there a lions club in my town", "is there a club near me"], "answer": "Use the Find a Club tool on the Lions website to see clubs near you, then contact one and attend a meeting or a service project. If no club suits you, you can start a new one. You can choose a club type that fits your life: traditional, specialty (shared interest), virtual (online), campus (students), club branch (a smaller group within an existing club) or Leo (ages 12 to 30).", "facts": ["Find a club: lionsclubs.org/en/join", "Membership questions: membership@lionsclubs.org", "Membership types include regular, family, student and Leo", "Ask \"what are the types of Lions clubs\" for details of each type"], "tags": ["join", "become", "membership", "member", "find a club", "locator", "near me", "sign up", "apply"], "related": ["club-types", "membership-types", "new-member-first-steps"], "src": ["join", "options", "club-types"]}, {"id": "club-types", "cat": "Joining", "level": "new", "title": "Types of Lions clubs", "questions": ["types of lions clubs", "what kinds of clubs are there", "traditional club", "specialty club", "virtual club", "which club should i join", "club options", "can i attend meetings online", "what is the difference between traditional and specialty clubs", "clubs that meet by video call", "can lions meet on zoom", "what are the different types of lions clubs", "what is a campus lions club", "what is a specialty club", "what is a virtual lions club"], "answer": "Lions clubs come in several types, so you can choose what fits your life. Traditional clubs meet locally and regularly. Specialty clubs unite members around a shared interest, hobby, cause or profession, with the same chartering process as other clubs. Virtual clubs plan and meet online or by phone and still coordinate in-person service. Campus Lions clubs are for students, on or off campus, and need at least five student charter members among the 20 minimum. Club branches are groups of at least five people who belong to an existing parent club but hold their own meetings and activities, led through a branch liaison. Leo clubs are for young people aged 12 to 30.", "facts": ["Traditional: service-minded people who meet locally and regularly", "Specialty: members share an interest, hobby, cause or profession", "Virtual: some or all meetings held remotely, good for busy or spread-out members", "Campus: students, on or off campus; at least 5 student charter members within the 20 minimum", "Club branch: at least 5 members, a parent club and a branch liaison; district governor notified", "Leo: Alpha 12 to 18, Omega 18 to 30"], "tags": ["club types", "traditional", "specialty", "virtual", "campus", "leo", "options", "online"], "related": ["campus-club", "leo-clubs", "club-branch", "membership-types"], "src": ["club-types", "options"]}, {"id": "membership-types", "cat": "Joining", "level": "new", "title": "Membership types and discounts", "questions": ["membership types", "family membership", "student membership", "lions dues discount", "can my family join together"], "answer": "Four main kinds of membership: regular, family, student, and Leo. Family membership is for relatives in the same household and has a reduced dues rate. Student membership is for students from the legal age of majority up to under 30 and gives a discount on international dues. Leo members, aged 12 to 30, pay no membership fee. Local club dues vary and are set by each club.", "facts": ["Children cannot be members but can take part in the Cub program", "Leo-Lion members get a 50% discount on international dues"], "tags": ["membership", "dues", "fees", "cost", "family", "student", "discount", "price", "how much"], "related": ["leo-lion", "campus-club", "how-to-join"], "src": ["club-types", "leo-lion", "campus"]}, {"id": "campus-club", "cat": "Joining", "level": "new", "title": "Campus Lions clubs", "questions": ["campus lions club", "lions club for students", "how to start a campus lions club", "student member program", "charter members for campus club"], "answer": "A Campus Lions club is open to any student, living on or off campus, full-time or part-time. To charter one you need at least 20 charter members, of whom at least five are students. The usual route is to get approved as a registered student club with your school's student activities office.", "facts": ["Benefits: service hours, resume-building training, networking, and Student Member Program discounts", "If the school does not approve, you can charter an independent Campus Lions club, but may lose the school's name, campus venues and funding", "Student Member Program covers students from legal age of majority to under 30"], "tags": ["campus", "student", "college", "university", "charter", "school"], "related": ["club-branch", "young-lions", "leo-lion"], "src": ["campus", "young-lions"]}, {"id": "club-branch", "cat": "Joining", "level": "member", "title": "Club branches", "questions": ["what is a club branch", "start a lions group with five people", "small lions group", "club branch requirements"], "answer": "A club branch is a small group that can meet and serve on its own while getting support from a parent Lions club. It needs only five members, so it suits people who want to form a group but do not have the 20 charter members a full club needs. Alumni of a Campus Lions club can also use a branch to stay connected.", "facts": ["Minimum members: five", "A full new Lions club needs 20 charter members"], "tags": ["club branch", "branch", "five members", "small group", "charter"], "related": ["campus-club", "club-types"], "src": ["campus"]}, {"id": "leo-clubs", "cat": "Youth", "level": "new", "title": "Leo clubs", "questions": ["what are leo clubs", "leo club age", "alpha leo omega leo", "how to start a leo club", "leo club fees", "leo club advisor", "sponsor a leo club", "how old do you have to be to join a leo club", "what is the age limit for leo", "what age can kids join leos", "programme for teenagers", "my teenager wants to volunteer"], "answer": "Leo clubs are youth programs sponsored by Lions clubs for people aged 12 to 30. Alpha Leo clubs are for ages 12 to 18, and Omega Leo clubs are for ages 18 to 30. A sponsoring Lions club names an advisor, ideally someone who enjoys working with young people.", "facts": ["One-time organisation fee: US$100 (certificate, officer kit, sponsor kit, lapel pins)", "Annual levy: US$100 per Leo club, billed to the sponsoring Lions club each July and waived in the year the club is certified", "To charter: organise the club and elect officers, then the sponsoring Lions club president submits the Leo Club Organization Report (Leo-51)", "Certification may take 4 to 6 weeks", "Two or more Lions clubs can jointly sponsor one Leo club"], "tags": ["leo", "leos", "alpha", "omega", "youth", "teen", "advisor", "sponsor", "levy", "leo-51"], "related": ["leo-lion", "youth", "club-types"], "src": ["leo-faqs", "club-types"]}, {"id": "leo-lion", "cat": "Youth", "level": "new", "title": "Leo-Lion program (Leos becoming Lions)", "questions": ["leo to lion", "leo lion program", "what happens when a leo ages out", "leo lion benefits", "leo-lion membership"], "answer": "The Leo-Lion program helps Leos move up into Lions. Current or former Leos who served at least a year and a day, from the legal age of majority through age 35, can join as Leo-Lions. They get a 50% discount on international dues, a waived entrance or charter fee, credit for their Leo years, and access to special scholarships and online learning.", "facts": ["Leo records are automatically closed on June 30 of the Lion year if the Leo has reached the maximum age", "Short-term dual Leo and Lion membership is allowed", "Leo-Lions can serve in any club type, and as liaisons to boards and councils"], "tags": ["leo lion", "leo-lion", "transition", "age out", "graduate", "young lions"], "related": ["leo-clubs", "young-lions", "membership-types"], "src": ["leo-lion"]}, {"id": "young-lions", "cat": "Youth", "level": "new", "title": "Young Lions", "questions": ["young lions", "lions for young adults", "under 30 lions", "young professionals lions", "student member"], "answer": "Young Lions are members aged roughly 40 or younger. If you are 30 or under and in school, the Student Member Program gives discounted dues and extra fee waivers. Campus clubs, specialty clubs, club branches and the Leo-Lion program are all aimed at helping younger people serve in a way that suits them.", "facts": ["Questions: membership@lionsclubs.org", "Young Lions have their own hub on the Lions website"], "tags": ["young lions", "young adults", "youth", "students", "under 30", "under 40"], "related": ["campus-club", "leo-lion", "club-types"], "src": ["young-lions", "gma"]}, {"id": "new-member-first-steps", "cat": "Joining", "level": "new", "title": "Your first steps as a new Lion", "questions": ["new member orientation", "i just joined lions what now", "first steps for new lion", "what should a new lion do first", "how do i begin as a new member"], "answer": "Start by going to your club meetings and joining its service projects. Register on the Lion Portal, complete the New Member Orientation course, and explore the Member Resource Center, which holds Lions news, resources and tools. Following Lions on social media is also encouraged.", "facts": ["Lion Portal: where members register and manage their Lions account", "Lions Learning Center: online courses, including New Member Orientation", "Member Resource Center: news, resources and information"], "tags": ["new member", "orientation", "getting started", "first steps", "lion portal", "learning center", "welcome", "onboarding"], "related": ["glossary-lion-portal", "how-to-join", "gst"], "src": ["new-members", "mrc"]}, {"id": "gst", "cat": "For members", "level": "member", "title": "Global Service Team (GST) toolbox", "questions": ["what is the global service team", "gst toolbox", "service reporting", "kindness matters award", "service journey learn discover act celebrate", "how do clubs report service"], "answer": "The Global Service Team helps clubs find resources and best practices to make their projects better. The toolbox covers service programs and planners, advocacy, service reporting, service awards and LCIF grants. Its service journey has four phases: Learn, Discover, Act and Celebrate.", "facts": ["Kindness Matters Service Award: clubs are nominated at club level; a few each year are recognised for outstanding projects in a global cause", "Lions-Elevance Health Volunteer Days: clubs in specified US cities can apply for grants up to US$2,500 each spring", "Related toolboxes: Global Action Team, Global Leadership Team, Global Membership Team"], "tags": ["gst", "global service team", "toolbox", "reporting", "awards", "kindness matters", "service journey", "advocacy"], "related": ["service-programs", "lcif-grants", "gma"], "src": ["gst"]}, {"id": "gma", "cat": "For members", "level": "member", "title": "Global Membership Approach", "questions": ["global membership approach", "how to grow lions membership", "revitalize a club", "start a new lions club", "get new members for my club", "rebuild a struggling club", "what does gma stand for"], "answer": "The Global Membership Approach is a step-by-step process that helps districts grow. It focuses on starting new clubs and bringing new members into existing clubs, then keeping members engaged. An eLearning course on it is available in the Lions Learning Center.", "facts": ["Related options: Campus clubs, Specialty clubs, Club branches, Young Lions", "Resources include a customizable \"We are Lions\" poster for marketing a club"], "tags": ["membership growth", "gma", "recruit", "new club", "revitalize", "rebuild", "retention"], "related": ["club-types", "mission-1-5"], "src": ["gma"]}, {"id": "mission-1-5", "cat": "For members", "level": "member", "title": "MISSION 1.5", "questions": ["mission 1.5", "1.5 million members goal", "mission 1.5 awards", "lions membership goal"], "answer": "MISSION 1.5 is Lions' goal of reaching 1.5 million members worldwide by 2027. The MISSION 1.5 Awards recognise growth in membership, and the Member Resource Center lists ways to recruit members.", "facts": ["Current membership is about 1.4 million", "Details and the latest award rules are on the Member Resource Center"], "tags": ["mission 1.5", "goal", "1.5 million", "awards", "growth", "2027"], "related": ["gma", "what-is-lions"], "src": ["mrc"]}, {"id": "structure", "cat": "structure", "level": "general", "title": "How Lions is organised", "questions": ["how is lions organised", "structure of lions clubs international", "lions hierarchy", "club district multiple district international", "levels of lions", "how is lions structured", "organisation structure of lions"], "answer": "Lions are organised in levels. A local club belongs to a district, led by a district governor. Zones and regions group clubs within a district for support. Districts can form a multiple district, supported by a council chairperson and the Council of Governors. At the top is Lions Clubs International, led by the International Board of Directors and the International President, who for 2026-27 is Mark S. Lyon. Lions Clubs International Foundation (LCIF) provides grants that support the service of members.", "facts": ["Club level: club president, vice president, secretary, treasurer and chairpersons", "District level: district governor and the district cabinet", "International level: executive officers and elected directors"], "tags": ["structure", "levels"], "related": ["titles-international", "titles-club"], "src": ["pg-dg", "pg-md", "pg-zone", "leaders-page", "about-node"]}, {"id": "advocacy", "cat": "For members", "level": "member", "title": "Advocacy for clubs", "questions": ["lions advocacy", "how can clubs advocate", "influence policy lions"], "answer": "Advocacy means a club using its voice to raise awareness, influence laws and policy, and build partnerships around the causes it serves. The Global Service Team toolbox has guidance for it.", "facts": ["Advocacy sits alongside service planning, reporting, awards and grants in the GST toolbox"], "tags": ["advocacy", "policy", "awareness", "partnerships"], "related": ["gst"], "src": ["gst"]}, {"id": "contact-lci", "cat": "Help", "level": "new", "title": "Contact Lions Clubs International", "questions": ["contact lions", "lions headquarters address", "lions phone number", "lions email", "membership email", "where is lions headquarters"], "answer": "Lions Clubs International headquarters is at 300 W. 22nd Street, Oak Brook, Illinois 60523-8842, USA. The main phone is +1 630 571 5466. For membership questions write to membership@lionsclubs.org.", "facts": ["Contact forms are on lionsclubs.org under Contact LCI and Contact LCIF"], "tags": ["contact", "address", "phone", "email", "headquarters", "oak brook", "help"], "related": ["how-to-join"], "src": ["mrc", "leo-lion"]}, {"id": "glossary-lion-portal", "cat": "Glossary", "level": "new", "title": "Lion Portal, MyLCI and Lions Learning Center", "questions": ["what is the lion portal", "what is mylci", "what is lions learning center", "what is the member resource center"], "answer": "These are the online tools for members. The Lion Portal is where you register and manage your Lions account, MyLCI is where clubs maintain membership records, the Lions Learning Center holds online courses, and the Member Resource Center collects news and resources.", "facts": ["Club secretaries typically use MyLCI to update member records"], "tags": ["lion portal", "mylci", "learning center", "member resource center", "online", "tools"], "related": ["new-member-first-steps"], "src": ["new-members", "leo-lion", "mrc"]}, {"id": "glossary-terms", "cat": "Glossary", "level": "new", "title": "Lions jargon in plain words", "questions": ["lions glossary", "what does lci mean", "what is a charter member", "what does charter mean", "lion year", "lions terms", "what is a leo"], "answer": "A Lion is a member. LCI is Lions Clubs International and LCIF is its foundation. A Leo is a youth member aged 12 to 30. Charter means officially founding a club, and charter members are the founding members. A district is a regional group of clubs. The Lions year runs July to June.", "facts": ["A new Lions club needs 20 charter members; a club branch needs five", "GST is the Global Service Team; GMA is the Global Membership Approach"], "tags": ["glossary", "terms", "jargon", "lci", "lcif", "charter", "lion", "leo", "district", "lion year", "meaning"], "related": ["structure", "lcif", "leo-clubs"], "src": ["leo-faqs", "campus", "mrc"]}, {"id": "titles-overview", "cat": "Officers and titles", "level": "member", "title": "Lions officer titles from club to International, in plain words", "questions": ["what are the lions officer titles", "lions positions and titles explained", "lions ranks", "lions structure from club to international for beginners", "what do all the lions titles mean", "who is who in lions titles and levels"], "answer": "Lions is organised like a ladder, and each rung has its own titles. Club: the president, vice presidents, secretary, treasurer and committee chairpersons run your local club. Zone: a zone chairperson looks after a small group of clubs (a region chairperson looks after several zones, where a district uses regions). District: a district governor, helped by the first and second vice district governors, leads all the clubs in an area, with a cabinet. Multiple district: where several districts are grouped, their governors form a council led by a council chairperson. International: the International President, vice presidents and directors lead the whole association, and the LCIF Chairperson leads the foundation. You only need to know the level you serve at; each rung supports the one below it.", "facts": ["Every Lions year runs July to June, and officers usually serve one year at a time", "A member only becomes a zone, region, district or international officer after serving at club level first", "Ask for any level: club, zone and region, district, multiple district, International, or LCIF area leaders"], "tags": ["titles", "officers", "hierarchy", "ranks", "structure"], "related": ["titles-club", "titles-zone-region", "titles-district", "titles-multiple-district", "titles-international", "lcif-leaders", "structure"], "src": ["mrc", "about-node"]}, {"id": "titles-district", "cat": "titles", "level": "district", "title": "District leadership roles", "questions": ["what positions are there in a lions district", "district officer titles", "who runs a lions district"], "answer": "The district governor is the chief representative of Lions International in the district. The governor leads membership growth, new club development and club retention, oversees the district Global Action Team, guides district goals, promotes leadership training and makes sure clubs follow association guidelines and stay in good standing. The governor also leads key meetings and conventions and supports LCIF. The Managing Your District page on lionsclubs.org lists the district cabinet structure, cabinet secretary and treasurer e-book, and other tools. A Lion who has served as district governor cannot be elected district governor or vice district governor again.", "facts": ["District Cabinet Structure and Cabinet Secretary / Treasurer e-Book: Managing Your District page", "Governance documents: Board Policy Manual and the Standard Constitutions"], "tags": ["district", "governor"], "related": ["structure"], "src": ["pg-dg"]}, {"id": "titles-multiple-district", "cat": "titles", "level": "multiple-district", "title": "Multiple district leadership roles", "questions": ["what is a multiple district", "council chairperson", "council of governors", "who runs a multiple district", "multiple district officers"], "answer": "A multiple district is supported by a council chairperson and a council secretary, who support the actions and decisions of the Council of Governors. Multiple districts also appoint chairpersons for areas such as Leo clubs, vision, diabetes, hunger, childhood cancer, environment, marketing, protocol, youth camps and exchange, and convention, and coordinators for the Global Leadership, Membership and Service Teams. The Managing Your Multiple District page on lionsclubs.org has the Council Chairperson e-Book, the Council Chairperson Orientation in the Lions Learning Center and the Council of Governors guide.", "facts": ["Council Chairperson e-Book and Orientation: Managing Your Multiple District page", "Multiple District Officers Report Form reports the council chairperson"], "tags": ["multiple district", "council"], "related": ["structure"], "src": ["pg-md"]}, {"id": "titles-international", "cat": "titles", "level": "international", "title": "International officers and directors", "questions": ["who is the international president", "international president of lions", "who are the international officers", "international officers and directors", "international board of directors", "lions international executive officers", "who is lions international president 2026-27", "international vice presidents"], "answer": "For 2026-27 the executive officers of Lions Clubs International are International President Mark S. Lyon (Brookfield, Connecticut, USA), Immediate Past International President A.P. Singh (Kolkata, India), First Vice President Dr. Manoj Shah (Nairobi, Kenya), Second Vice President Tony Benbow (South Vermont, Australia) and Third Vice President C. Robert Rettby (Neuchatel, Switzerland). The International Board of Directors also includes second-year and first-year international directors, and the board has appointees, Leo-Lion Board Liaisons and standing committees such as Constitution and By-Laws, Membership Development, Marketing and Service Activities.", "facts": ["Source: Our Leaders (2026-2027) page on lionsclubs.org", "Leaders change each Lions year: check the page for the current list"], "tags": ["international", "president", "board"], "related": ["structure"], "src": ["leaders-page"]}, {"id": "lcif-leaders", "cat": "Officers and titles", "level": "member", "title": "LCIF area leaders and coordinators", "questions": ["what are lcif area leaders", "what is an lcif coordinator", "what is a district lcif coordinator", "what does the lcif multiple district coordinator do", "who leads lcif"], "answer": "The Lions Clubs International Foundation has its own ladder of volunteers. LCIF area leaders are appointed by the LCIF Chairperson, usually for a three-year term, to represent the foundation across a large area. Below them each multiple district has an LCIF coordinator who acts as an ambassador for LCIF, then district coordinators, and finally the club LCIF coordinator in each club, who promotes giving and grants to members.", "facts": ["LCIF area leaders are appointed by the LCIF Chairperson, usually for three years", "The LCIF Chairperson is a separate role from the International President", "See the LCIF Leadership Toolkit for each role's responsibilities"], "tags": ["lcif", "area leader", "coordinator", "foundation"], "related": ["titles-international", "titles-district", "titles-club"], "src": ["lcif-toolkit"]}, {"id": "logo-brand", "cat": "Marketing", "level": "member", "title": "Using the Lions logo and brand", "questions": ["how do i use the lions logo", "can i use the lions logo", "where can i get the lions logo", "lions logo for my club", "lions brand guidelines", "lions emblem download", "logo permission for a website"], "answer": "Lions International keeps the logo, emblem and brand rules on its Brand Guidelines, Logos and Brand page, so every club's materials look consistent. Brand-approved versions of the Lions emblem, icons and logos for clubs are on the Logos and Emblems page, and the Lions International Brand Guidelines document explains how to use them. Social media kits and Canva templates you can customise for your club are also provided. Use the approved files rather than copying a logo from a website.", "facts": ["Brand guidelines: the Lions International Brand Guidelines document is in the library", "Ready-made social media graphics and Canva templates are on the Social Media Kits page", "If you are unsure whether a use is allowed, ask Lions International before you publish"], "tags": ["logo", "emblem", "brand", "guidelines"], "related": ["titles-club"], "src": ["brand-page"]}, {"id": "cause-humanitarian", "cat": "Service", "level": "both", "title": "Humanitarian: meeting the world's most crucial needs", "questions": ["lions humanitarian", "humanitarian aid lions", "what is the humanitarian cause", "lions humanitarian efforts"], "answer": "Humanitarian is one of Lions' eight global causes. Lions identify the world's most crucial needs and provide humanitarian aid where it is needed most, through local clubs and through grants from the Lions Clubs International Foundation.", "facts": ["Listed as a global cause on the Lions website", "Disaster relief is a separate cause for natural disasters", "Clubs can find project ideas under Service Programs on lionsclubs.org"], "tags": ["humanitarian", "aid", "relief"], "related": ["global-causes", "disaster-relief", "lcif"], "src": ["service-programs"]}, {"id": "join-cost", "cat": "membership", "level": "general", "title": "What Lions membership costs", "questions": ["how much does it cost to join lions", "what is the cost of joining a lions club", "membership fees for lions", "lions dues and fees", "how much are lions dues", "entrance fee for lions club", "is it expensive to join lions", "what are the charges to be a lion", "cost of lions membership", "lions club membership fee"], "answer": "Joining a Lions club involves international dues plus a charter or entrance fee, and the current amounts are in the Membership Dues and Fees Chart (TK-40) on lionsclubs.org. Your club will tell you its own local dues. There are discounts: students aged 30 and younger pay half the international dues and have the charter or entrance fee waived; family membership gives a 50% discount on international dues for up to four family members in the same household who join the same club as a full-paying member; and Leo-Lions get 50% off international dues and a fee waiver. Students over 30 joining a Campus Lions club pay a discounted charter or entrance fee of US$10.00 and full international dues.", "facts": ["Current amounts: Membership Dues and Fees Chart (TK-40) on lionsclubs.org", "Student members (30 and younger): half international dues, fee waiver", "Family membership: 50% off international dues for up to four household members", "Leo-Lion: 50% off international dues, fee waiver"], "tags": ["cost", "dues", "fees"], "related": ["membership-types"], "src": ["pg-stu", "pg-fam", "leo-lion", "pg-pay"]}, {"id": "pay-dues", "cat": "Finance", "level": "member", "title": "How a club pays its international dues", "questions": ["how do i pay dues", "how do i pay club dues", "how do i pay international dues", "how does a club treasurer pay dues", "how do i pay my dues online"], "answer": "The club treasurer pays in the Lion Portal: log in, choose My Club, then Club Statements, and select Pay with PayPal or Pay Now. If you pay by bank deposit instead, the Payment Instructions page lists the details for each country.", "facts": ["Canada has a pre-authorised debit agreement form, and India has a NEFT payment detail form", "Use the Exchange Rates page for the rate to apply when you pay in another currency", "The Unidentified Deposits list shows deposits that could not be matched to a club or district", "The Finance Resources page also links current membership dues and fees, online statements and the Suspension Policy"], "tags": ["pay", "payment", "dues", "treasurer", "statement", "paypal"], "related": ["join-cost"], "src": ["pg-pay", "pg-fin"]}, {"id": "report-service", "cat": "Service", "level": "member", "title": "How to report a service project", "questions": ["how do i report service", "how do i report a service project", "how to report service activities", "when do i report service", "why report service"], "answer": "Report each service activity in the Lion Portal as soon as possible after you complete it. The Lion year ends on June 30, but reports for that year can still be entered until July 31. The Service Activity Information resource helps you collect what you need, including the list of global causes and project types.", "facts": ["Clubs that report service become eligible for the Kindness Matters Service Award and the Excellence Awards", "Reporting shows the club's impact, inspires new members and helps leaders guide service", "In the last fiscal year Lions and Leos, with LCIF support, improved the lives of 410 million people"], "tags": ["report", "service", "reporting", "portal", "activity"], "related": ["global-causes", "titles-club"], "src": ["pg-svc"]}, {"id": "insurance", "cat": "Legal", "level": "member", "title": "Insurance for Lions clubs and events", "questions": ["are lions clubs insured", "how do i get insurance for an event", "lions liability insurance", "do lions have insurance", "insurance for a club event", "what insurance do lions clubs have"], "answer": "All Lions clubs and districts are automatically covered by the association's Commercial General Liability program, worldwide. You can produce your own certificate of insurance as evidence of that cover, for example when a venue asks for one.", "facts": ["Certificate of insurance: there is a printable online version for the U.S. (2026-2027) and request forms for the U.S., Canada and the rest of the world", "The program includes a General Liability booklet and a Self-Inspection Checklist (both revised 2025) for fundraising activities", "In the United States only, clubs and districts can add supplemental cover: Directors and Officers Liability, Crime/Fidelity, Additional Liability and Accident insurance", "Additional Liability sits on top of the US$1,000,000 that is provided automatically", "Questions: DSP Insurance Services, Inc., (847) 934-6100 or (800) 316-6705"], "tags": ["insurance", "liability", "certificate", "event", "coverage"], "related": ["titles-club"], "src": ["pg-ins", "pg-cert"]}, {"id": "matching-grant", "cat": "Grants", "level": "member", "title": "LCIF Matching Grants: amounts, deadlines and how to apply", "questions": ["what is a matching grant", "how do i apply for a matching grant", "matching grant amount", "matching grant deadlines", "how much is a matching grant", "lcif matching grant"], "answer": "A Matching Grant gives capital funding for Lions-initiated humanitarian service projects, with priority for equipment and infrastructure. Grants range from US$10,000 to US$150,000. Projects in developing countries can receive up to 75 percent of the total project budget, and in developed countries up to 50 percent.", "facts": ["Applications are considered by the LCIF Board of Trustees three times a year, in August, January and May", "Application deadlines are February 1, May 1 and October 1: apply well before them", "The grant administrator must send LCIF a final report within 45 days of finishing the project", "Examples: schools and orphanages, facilities for people with disabilities, charitable medical facilities"], "tags": ["matching grant", "grant", "lcif", "capital", "apply"], "related": ["lcif", "global-causes"], "src": ["pg-mg"]}, {"id": "start-leo-club", "cat": "Leo", "level": "member", "title": "How to start a Leo club", "questions": ["how do i start a leo club", "how do i sponsor a leo club", "what does it cost to start a leo club", "what are leo club types", "what are alpha and omega leos"], "answer": "A Lions club sponsors a Leo club. First choose a Leo club advisor and decide the type: a community-based club open to any eligible young person, or a school-based club run in a school with extra leadership from school staff. Then choose the track by age: Alpha Leos are 12 to 18 and Omega Leos are 18 to 30.", "facts": ["Fees: a one-time organisation fee starting at US$100 and an annual Leo club sponsor levy of US$100, both of which may increase", "The Leo Club Starter Guide explains how to choose an advisor and lists the steps", "Leo members pay no membership fee"], "tags": ["leo", "start", "sponsor", "alpha", "omega", "advisor"], "related": ["leo-clubs", "leo-lion"], "src": ["pg-leo"]}, {"id": "student-join", "cat": "Joining", "level": "member", "title": "Joining Lions as a student", "questions": ["can i join as a student", "student membership discount", "how do students join lions"], "answer": "Yes. Students aged 30 and younger can join or charter any type of club at a discount: they pay half the international dues and the charter or entrance fee is waived. Campus Lions clubs are open to any student, full-time or part-time, living on or off campus.", "facts": ["Students over 30 joining a campus Lions club pay a discounted charter or entrance fee of US$10", "A student member certification worksheet confirms eligibility"], "tags": ["student", "campus", "discount", "join"], "related": ["join-cost", "campus-club", "membership-types"], "src": ["pg-stu"]}, {"id": "recruit-members", "cat": "Membership", "level": "member", "title": "How to recruit new members", "questions": ["how do i recruit members", "how do i recruit new members", "how to get new members for my club", "member recruitment steps", "how to attract members to a lions club"], "answer": "Recruitment is something every member can do, in four steps: 1) Just ask: invite friends, family, colleagues or neighbours you think would make good Lions, because a personal invitation is one of the most effective ways to bring in members. 2) Advocate for your club: talk about its impact and share personal stories. 3) Engage prospects directly: have a real conversation about how they can make a difference, and connect them with service that matches their interests. 4) Promote your service on social media: share photos and invite people to upcoming events.", "facts": ["The Just Ask! New Member Recruiting Guide and quick tips are on the Club Membership Chairperson page", "Run a new member orientation and induction ceremony once someone joins", "Clubs can also add members through a club branch or a family or student membership"], "tags": ["recruit", "recruitment", "new members", "invite", "grow"], "related": ["join-cost", "student-join", "gma"], "src": ["pg-rec", "pg-mem"]}, {"id": "start-new-club", "cat": "Membership", "level": "member", "title": "How to start a new Lions club", "questions": ["how do i start a new club", "how do i start a new lions club", "how to charter a new club", "steps to start a new lions club", "how to form a lions club"], "answer": "Follow these steps: 1) Read the New Club Development Guide and, if you can, attend or host a New Club Development Workshop. 2) Build a team and work with the new club's Guiding Lion. 3) Assess community needs with the Community Needs Assessment. 4) Promote the club and recruit members, for example with the Hello Brochure and a Just Ask! workshop. 5) Hold an informational night meeting and an organizational meeting. 6) Complete the application documents: the Charter Application Worksheet, charter member applications and the Report of Charter Members, then report the club in the Lion Portal. 7) Celebrate with a charter night, where the club receives its charter.", "facts": ["Districts can get Membership Development Grants and New Voices Grants towards club development costs", "The Membership Dues and Fees Chart shows current dues and fees for charter members", "Lions who help charter a club can earn Extension Awards"], "tags": ["start", "new club", "charter", "chartering", "form a club"], "related": ["club-branch", "recruit-members"], "src": ["pg-new"]}, {"id": "district-governor-role", "cat": "District leaders", "level": "member", "title": "What a district governor does", "questions": ["what is a district governor", "what does a district governor do", "district governor role", "district governor responsibilities", "role of dg"], "answer": "The district governor is Lions International's chief representative in the district. The governor leads membership growth, new club development and club retention, oversees the district Global Action Team, guides the district goals and promotes leadership and skills training.", "facts": ["Makes sure clubs follow association guidelines and remain in good standing", "Leads key meetings and conventions and builds teamwork across the district", "Supports LCIF initiatives", "Governors serve one year; a past district governor cannot be elected governor or vice district governor again"], "tags": ["district governor", "dg", "governor"], "related": ["titles-district"], "src": ["pg-dg"]}, {"id": "club-president-role", "cat": "Club officers", "level": "member", "title": "What the club president and vice president do", "questions": ["what does a club president do", "what does the club president do", "what does a vice president do", "club president responsibilities"], "answer": "The club president and vice president oversee club operations, preside over board meetings and lead the club's Global Action Team. Their responsibilities include appointing qualified leaders, following constitutional and legal requirements, guiding and supporting members, and working with district teams on initiatives.", "facts": ["The key reference is the Standard Club Constitution and By-Laws", "The Club Officer Guide describes every officer's role", "Keeping Lion Portal reporting current is part of every club officer's job"], "tags": ["president", "vice president", "club officer"], "related": ["titles-club"], "src": ["pg-club"]}, {"id": "club-secretary-role", "cat": "Club officers", "level": "member", "title": "What the club secretary does", "questions": ["what does a club secretary do", "what does the club secretary do", "club secretary responsibilities", "secretary role in a lions club"], "answer": "The club secretary is the link between the club, the district and Lions International. The secretary keeps accurate records, such as meeting minutes, attendance and financial documents, and helps create the club calendar.", "facts": ["Supports smooth operations and member engagement", "Reporting membership and officers in the Lion Portal is normally a secretary task", "See the Club Officer Guide for the full role"], "tags": ["secretary", "minutes", "records"], "related": [], "src": ["pg-club"]}, {"id": "club-treasurer-role", "cat": "Club officers", "level": "member", "title": "What the club treasurer does", "questions": ["what does a club treasurer do", "what does the club treasurer do", "club treasurer responsibilities", "treasurer role in a lions club"], "answer": "The club treasurer handles the club's finances: collecting and depositing funds, working with the secretary to send members their dues statements, and reporting payments to the board. The treasurer pays bills as approved, keeps all financial records, and gives the board monthly and semi-annual financial updates.", "facts": ["Pays the club's international dues in the Lion Portal (My Club, Club Statements)", "Best Practice for Financial Transparency is a recommended resource"], "tags": ["treasurer", "finances", "funds"], "related": ["pay-dues"], "src": ["pg-club", "pg-pay"]}, {"id": "lions-year", "cat": "Basics", "level": "both", "title": "When the Lions year runs", "questions": ["when does the lions year start", "when does the lions year end", "what is the lions year", "lions fiscal year", "when do officers take office"], "answer": "The Lions year (fiscal year) runs from July 1 to June 30. Officers' terms follow that year. Service for a year can still be reported in the Lion Portal until July 31.", "facts": ["Dues are paid per half-year, based on June and December membership reports", "International officers are elected at the annual International Convention"], "tags": ["year", "fiscal", "july", "june"], "related": ["report-service"], "src": ["pg-svc"]}, {"id": "history", "cat": "history", "level": "general", "title": "A short history of Lions", "questions": ["what is the history of lions", "history of lions clubs", "who founded lions clubs", "when was lions clubs international founded", "when did lions start", "lions history timeline", "who started lions", "who started the lions club"], "answer": "Lions began in 1917, when a Chicago businessman named Melvin Jones invited business clubs from around the USA to a meeting where the Association of Lions Clubs was formed. It became international in 1920 with the Border Cities Lions Club in Windsor, Canada. In 1925 Helen Keller challenged Lions to become knights of the blind. Leos were introduced in 1957, Lions Clubs International Foundation (LCIF) was created in 1968, and Lions welcomed their millionth member in 1973. Lions turned 100 in 2017, and today there are more than 1.4 million members in about 50,000 clubs.", "facts": ["1917: founded in Chicago by Melvin Jones", "1920: first club outside the USA, in Windsor, Canada", "1925: Helen Keller's challenge to Lions", "1945: Lions help establish the NGO section of the United Nations", "1957: Leo program begins", "1968: LCIF created", "1973: one millionth member", "1990: SightFirst launched", "2017: Lions turn 100 (Centennial Convention, Chicago)"], "tags": ["history", "founder", "melvin jones"], "related": ["helen-keller", "what-is-lions"], "src": ["mission-history"]}, {"id": "helen-keller", "cat": "history", "level": "general", "title": "Helen Keller and Lions", "questions": ["who was helen keller", "helen keller and lions", "knights of the blind", "why is helen keller important to lions", "helen keller day"], "answer": "Helen Keller was born in Tuscumbia, Alabama, USA, in 1880 and became blind and deaf after a fever at 18 months. She became a tireless advocate for people with disabilities. In 1925 she attended the Lions Clubs International Convention and challenged Lions to become knights of the blind in the crusade against darkness. Lions accepted, and their work ever since has included sight programs aimed at preventable blindness. In 1971 the International Board declared June 1 as Helen Keller Day.", "facts": ["1925: the challenge was made at the International Convention in Cedar Point, Ohio, USA", "June 1 is Helen Keller Day; Lions run sight-related service projects that day"], "tags": ["helen keller", "vision"], "related": ["cause-vision", "history"], "src": ["pg-helen", "mission-history"]}, {"id": "governing-documents", "cat": "clubrules", "level": "general", "title": "Constitution and by-laws: where to read the official documents", "questions": ["club constitution", "what is the club constitution", "lions constitution and by laws", "international constitution and by-laws", "district constitution and by-laws", "multiple district constitution", "where can i find the constitution", "standard club by-laws", "quorum for a club meeting", "membership categories honorary life associate", "what is a life member", "what is an honorary member", "what is an affiliate member", "who can be a lions member admission rules", "club officers duties by-laws", "what is a tail twister", "what is a lion tamer", "club board of directors quorum", "how are club officers elected", "how do i amend the club constitution", "what are the purposes of lions clubs international", "lions code of ethics full text", "how to conduct a club meeting", "order of business at a meeting", "what is robert's rules"], "answer": "The rules that govern Lions are published by Lions Clubs International on lionsclubs.org, so this guide does not summarise them. In the Resource Center, under Governance, you can open the Standard Form Lions Club Constitution and By-Laws, the District and Multiple District versions, and the International Constitution and By-Laws. They cover membership categories, officers and board positions, elections, meetings and quorum, dues, and amendments. A club's own by-laws can differ from the standard form, so check your club's copy as well.", "facts": ["Open the Resource Center and filter by Governance", "Standard Form Lions Club Constitution and By-Laws (PDF and Word)", "International Constitution and By-Laws (PDF)", "Board Policy Manual: lionsclubs.org Legal Resources page"], "tags": ["constitution", "by-laws", "governance"], "related": [], "src": ["rc-library", "pg-legal"]}, {"id": "titles-club", "cat": "titles", "level": "club", "title": "Club leadership roles", "questions": ["what positions are there in a lions club", "lions club officer titles", "club officer titles", "who runs a lions club", "what are the roles in a lions club", "club positions"], "answer": "Lions clubs are led by their club officers. The Member Resource Center has an official guide for each role: the club president and vice president, who oversee club operations, preside over board meetings and lead the Global Action Team; the club secretary, who links the club with the district and Lions International and keeps records; the club treasurer, who handles club finances and dues statements; and the membership, service and marketing communications chairpersons. A club's own by-laws set the full list of positions, so check your club's copy of the Standard Club Constitution and By-Laws on lionsclubs.org.", "facts": ["Club Officer Guide: lionsclubs.org Managing Your Club page", "Role pages: Club President and Vice President, Club Secretary, Club Treasurer, Club Membership Chairperson, Club Service Chairperson, Club Marketing Communications Chairperson"], "tags": ["officers", "club"], "related": ["governing-documents"], "src": ["pg-club", "pg-mem", "pg-mkt"]}, {"id": "titles-zone-region", "cat": "titles", "level": "zone-region", "title": "Zone and region chairpersons", "questions": ["what does a zone chairperson do", "what does a region chairperson do", "zone chairperson role", "region chairperson role", "zone and region chairperson"], "answer": "Zone and region chairpersons support clubs within a district. The Zone and Region Chairperson Center on lionsclubs.org gathers their tools: the Zone Chairperson Learning Map, the Global Membership Approach resources, a zone meeting PowerPoint, the District Governor's Advisory Committee meeting report, meeting preparation checklist, minutes template and evaluation, and webinars such as The Successful Zone Chairperson. Open the page for the full set.", "facts": ["Zone Chairperson Workshop is available in the Lions Learning Center", "Club visit and club health resources are on the same page"], "tags": ["zone", "region"], "related": ["structure"], "src": ["pg-zone"]}, {"id": "global-action-team", "cat": "titles", "level": "district", "title": "The Global Action Team (GAT)", "questions": ["what is the global action team", "what is gat", "what is the global leadership team", "what is the global membership team", "what is the global extension team", "what is a gmt coordinator", "what is a district gmt coordinator", "what is glt"], "answer": "The Global Action Team (GAT) is a network of Lions at every level who help districts reach their MISSION 1.5 targets, which means growing club membership, building leaders and raising Lions' visibility through service. It has four teams: the Global Membership Team (GMT), which recruits members and promotes good member experiences; the Global Extension Team (GET), an offshoot of GMT that starts new clubs in the district; the Global Leadership Team (GLT), which develops Lion and Leo leaders; and the Global Service Team (GST), which helps clubs improve their service projects and use Lions and LCIF programs and grants. Each team has coordinators, and the district governor oversees the district's GAT.", "facts": ["MISSION 1.5 is the drive to reach 1.5 million members worldwide by July 1, 2027", "Coordinator role descriptions and annual checklists are on each team's toolbox page", "A Global Action Team course is in the Lions Learning Center"], "tags": ["gat", "gmt", "glt", "gst", "get"], "related": ["titles-district"], "src": ["pg-gat", "pg-gatr", "pg-gmt", "pg-glt", "pg-gst"]}]};